import sqlite3, json
from contextlib import closing
db = sqlite3.connect("file:out/state_live_practice/nova.sqlite3?mode=ro", uri=True)
with closing(db):
    for doc, d in db.execute("SELECT doc, data_json FROM facts WHERE kind='contracts' AND doc LIKE '%.pdf'"):
        d = json.loads(d)
        print("==", doc, d["contract_id"], d["kind"], "carrier_code:", d.get("carrier_code"), "shipper_code:", d.get("shipper_code"))
        for b in ("pricing_rules", "precedence", "term", "payment"):
            blk = {k: v for k, v in (d.get(b) or {}).items() if k != "source"}
            print(f"  {b}: {json.dumps(blk, ensure_ascii=False)[:600]}")
        for ch in d.get("amendment_changes") or []:
            print("  change:", {k: v for k, v in ch.items() if k != "source"})
    for (d,) in db.execute("SELECT data_json FROM facts WHERE kind='accessorials' AND data_json LIKE '%PEAK%'"):
        print("PEAK accessorial:", {k: v for k, v in json.loads(d).items() if k != '_source'})
EOF

