            c.trace["lines"].append({"label": line.get("charge_label"), "amount": str(billed), "waiver": waiver.doc,
                                     "waived_by": person.name})
            for ev in (waiver.evidence(), person.fact.evidence(), line.evidence()):
                c.add_evidence(ev)
    return list(found.values())

