            "has_key": "ANTHROPIC_API_KEY" in os.environ, "marker": os.environ.get("LOGIN_HOME"),
            "stdin": doc, "cwd_empty": os.listdir(".") == [], "sysroot": os.environ.get("SYSTEMROOT")}
    if mode == "structured":
